        )
        
        case 2: return .yearMonth(year: try FfiConverterInt32.read(from: &buf), month: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 3: return .yearMonthDay(year: try FfiConverterInt32.read(from: &buf), month: try FfiConverterUInt8.read(from: &buf), day: try FfiConverterUInt8.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
